class Solution {
public:
    string oddString(vector<string>& words) {
        int m = (int)words.size();
        int n = (int)words[0].size();
        auto diff = [&](int i, int j) -> int {
            return words[i][j + 1] - words[i][j];
        };
        auto same = [&](int a, int b) -> bool {
            for (int j = 0; j < n - 1; j++) {
                if (diff(a, j) != diff(b, j)) return false;
            }
            return true;
        };
        if (!same(0, 1)) {
            if (same(0, 2)) return words[1];
            return words[0];
        }
        for (int i = 2; i < m; i++) {
            if (!same(0, i)) return words[i];
        }
        return "";
    }
};
